import{_ as e,o as a,c as s,a5 as d}from"./chunks/framework.CXroN2RO.js";const p=JSON.parse('{"title":"設計ケーススタディの読み進め方","description":"","frontmatter":{"title":"設計ケーススタディの読み進め方","study":{"source":"C++ Wiki","status":"published","summary":"設計原則やパターンの知識を「実際のゲーム機能の設計判断」として使う章です。各ケースは共通の型で進みます:","section":"learning","format":"path","domain":"design","collection":"cpp-design","order":11}},"headers":[],"relativePath":"design/case-studies/index.md","filePath":"design/case-studies/index.md"}'),r={name:"design/case-studies/index.md"};function n(i,t,h,u,o,l){return a(),s("div",null,[...t[0]||(t[0]=[d('<div id="第11部-ケーススタディ" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="設計ケーススタディの読み進め方" tabindex="-1">設計ケーススタディの読み進め方 <a class="header-anchor" href="#設計ケーススタディの読み進め方" aria-label="Permalink to &quot;設計ケーススタディの読み進め方&quot;">​</a></h1><p>設計原則やパターンの知識を「<strong>実際のゲーム機能の設計判断</strong>」として使う章です。各ケースは共通の型で進みます:</p><ol><li><strong>素朴な実装</strong>(まず動くもの)</li><li><strong>機能追加で破綻する過程</strong>(何が要求されると崩れるか)</li><li><strong>複数の設計案</strong>(継承案/コンポジション案/パターン適用案/パターンを使わない簡潔案)</li><li><strong>利点と欠点の比較</strong></li><li><strong>規模別の判断</strong>(小=ジャム・プロト/中=数人・数ヶ月/大=チーム・長期運用)</li></ol><p>「正解」は規模と要求で変わります。<strong>どの案も選べる状態</strong>になることがこの章のゴールです。</p><h2 id="ケース一覧" tabindex="-1">ケース一覧 <a class="header-anchor" href="#ケース一覧" aria-label="Permalink to &quot;ケース一覧&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ケース</th><th>主に効いてくる知識</th></tr></thead><tbody><tr><td><a href="/study/design/case-studies/player-input.html">01. プレイヤー入力</a></td><td><a href="/study/design/patterns/command.html">Command</a>、<a href="/study/game/patterns/command-buffer-and-input.html">入力抽象化</a>、<a href="/study/design/solid/dip.html">DIP</a></td></tr><tr><td><a href="/study/design/case-studies/weapon-switching.html">02. 武器切り替え</a></td><td><a href="/study/design/patterns/strategy.html">Strategy</a>、<a href="/study/design/foundations/inheritance-delegation-composition.html">継承vsコンポジション</a></td></tr><tr><td><a href="/study/design/case-studies/enemy-ai.html">03. 敵AI</a></td><td><a href="/study/game/patterns/state-machines.html">FSM</a>、<a href="/study/game/patterns/behavior-tree-and-blackboard.html">BT</a>、<a href="/study/game/patterns/type-object-and-sandbox.html">Type Object</a></td></tr><tr><td><a href="/study/design/case-studies/status-effects.html">04. ステート異常</a></td><td><a href="/study/design/patterns/decorator.html">Decorator</a>、効果リスト、<a href="/study/design/patterns/state.html">State</a></td></tr><tr><td><a href="/study/design/case-studies/achievements.html">05. 実績システム</a></td><td><a href="/study/design/patterns/observer.html">Observer</a>、<a href="/study/game/patterns/event-queue-and-pubsub.html">Pub/Sub</a>、データ駆動</td></tr><tr><td><a href="/study/design/case-studies/save-data.html">06. セーブデータ</a></td><td><a href="/study/design/patterns/memento.html">Memento</a>、<a href="/study/design/solid/srp.html">SRP</a>、バージョン互換</td></tr><tr><td><a href="/study/design/case-studies/damage-calculation.html">07. ダメージ計算</a></td><td>パイプライン、<a href="/study/design/patterns/chain-of-responsibility.html">Chain of Responsibility</a>、純粋関数</td></tr><tr><td><a href="/study/design/case-studies/ui-notification.html">08. UI通知</a></td><td><a href="/study/design/patterns/observer.html">Observer</a>、<a href="/study/game/patterns/mvc-mvp-mvvm.html">MVP</a>、<a href="/study/game/patterns/event-queue-and-pubsub.html">Event Queue</a></td></tr><tr><td><a href="/study/design/case-studies/object-spawning.html">09. オブジェクト生成</a></td><td><a href="/study/design/patterns/factory-method.html">Factory</a>、<a href="/study/design/patterns/prototype.html">Prototype</a>、<a href="/study/game/patterns/object-pool.html">Object Pool</a></td></tr><tr><td><a href="/study/design/case-studies/screen-transition.html">10. 画面遷移</a></td><td><a href="/study/design/patterns/state.html">State/Stack</a>、<a href="/study/design/patterns/facade.html">Facade</a></td></tr><tr><td><a href="/study/design/case-studies/sound-manager.html">11. サウンド管理</a></td><td><a href="/study/design/patterns/facade.html">Facade</a>、<a href="/study/design/patterns/adapter.html">Adapter</a>、<a href="/study/game/patterns/event-queue-and-pubsub.html">Event Queue</a></td></tr><tr><td><a href="/study/design/case-studies/item-effects.html">12. アイテム効果</a></td><td><a href="/study/game/patterns/type-object-and-sandbox.html">Type Object</a>、<a href="/study/design/patterns/command.html">Command</a>、データ駆動</td></tr><tr><td><a href="/study/design/case-studies/quest-system.html">13. クエスト</a></td><td><a href="/study/design/patterns/composite.html">Composite</a>、<a href="/study/design/patterns/observer.html">Observer</a>、<a href="/study/design/patterns/interpreter.html">Interpreter</a></td></tr><tr><td><a href="/study/design/case-studies/event-notification.html">14. イベント通知</a></td><td><a href="/study/design/patterns/observer.html">Observer</a> vs <a href="/study/game/patterns/event-queue-and-pubsub.html">Queue</a> vs Bus 総合判断</td></tr><tr><td><a href="/study/design/case-studies/aim-control.html">15. 照準制御</a></td><td><a href="/study/design/patterns/strategy.html">Strategy</a>、補正パイプライン、<a href="/study/game/patterns/game-loop-and-update.html">Update順序</a></td></tr></tbody></table><p>仕上げに <a href="/study/design/case-studies/exercises.html">演習</a>。</p><h2 id="読み方のコツ" tabindex="-1">読み方のコツ <a class="header-anchor" href="#読み方のコツ" aria-label="Permalink to &quot;読み方のコツ&quot;">​</a></h2><ul><li>自分のプロジェクトに近い規模の判断を最初に読む(全部の案を実装する必要はない)</li><li>「破綻する過程」が自分の経験と一致するかを確かめながら読む——<strong>破綻を経験する前に設計を上げるのは早すぎる抽象化</strong>(<a href="/study/design/foundations/yagni-kiss-dry.html">YAGNI</a>)になりがち</li></ul><hr><p><a href="/study/guide/cpp-index.html">全体目次</a> | 次: <a href="/study/design/case-studies/player-input.html">プレイヤー入力</a></p>',12)])])}const g=e(r,[["render",n]]);export{p as __pageData,g as default};
